<section class="admin-content"><div class="admin-heading"><div><div class="eyebrow">مرکز کنترل پلتفرم</div><h1><?= e($title) ?></h1><p class="muted"><?= e($description) ?></p></div><a class="button" href="<?= url('/admin') ?>">بازگشت به داشبورد</a></div><div class="admin-panel"><div class="filter-links"><a href="<?= url('/admin/'.$table) ?>">همه</a><a href="<?= url('/admin/'.$table.'?limit=25') ?>">آخرین موارد</a></div><div class="table-wrap"><table><thead><tr><?php foreach ($columns as $column): ?><th><?= e(ucwords(str_replace('_',' ', $column))) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><?php foreach ($columns as $column): ?><td><?= e((string)($row[$column] ?? '—')) ?></td><?php endforeach; ?></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td class="empty" colspan="<?= count($columns) ?: 1 ?>">رکوردی برای نمایش وجود ندارد.</td></tr><?php endif; ?></tbody></table></div></div></section>